  "settings.clearLibraryConfirm": "Очистити всю бібліотеку? (треки, альбоми, виконавці)\nБуде ВТРАЧЕНО, і жодне сканування цього не відновить: вміст плейлистів (локальні треки), оцінки альбомів, закладки, обране, складені вручну бокс-сети й редагування альбомів.\nЗони, радіо, налаштування й назви плейлистів зберігаються. Резервна копія бази даних створюється автоматично безпосередньо перед цим (крім PostgreSQL).\nПовне сканування, навпаки, зберігає бокс-сети й редагування альбомів.",
