  "devices.gainTrimFixedVolume": "Фіксовану гучність увімкнено: корекція не діє (bit-perfect).",
  "devices.gainTrimPositiveIgnoredHardware": "Мережева зона з апаратною гучністю: додатна корекція не діє; Tune ніколи не надсилає на пристрій більше за запитану гучність (безпека). Застосовується лише від'ємна корекція.",
