  "settings.cleanupMovedGo": "Відкрити інструменти бібліотеки",
  "settings.clearLibraryV2Hint": "Очищає індекс (треки, альбоми, виконавці). Разом із ним втрачаються: вміст плейлистів, оцінки, закладки, обране, складені вручну бокс-сети й редагування альбомів. Жоден музичний файл не видаляється. Безпосередньо перед цим створюється резервна копія бази даних. Сканування повертає лише треки. Щоб оновити бібліотеку, краще запустіть повне сканування: воно зберігає бокс-сети й редагування альбомів.",
