  "settings.cloudListens": "Надсилати мої прослуховування до мого облікового запису",
  "settings.cloudListensHint": "Додає прослуховування з цього сервера на сторінку «Мої прослуховування» вашого облікового запису разом з іншими вашими серверами Tune. Для кожного прослуховування: дата, тривалість, непрозорий ідентифікатор профілю, назва, виконавець, альбом і, якщо відомі, ISRC та ідентифікатор MusicBrainz. Ніколи — шляхи до ваших файлів, IP-адреса чи назви зон. Типово вимкнено.",
