  "outputModule.notLinkedBody": "Це не проблема встановлення, і ваш ліцензійний ключ тут ні до чого. Права на платні модулі прив'язані до вашого облікового запису Mozaiklabs, а не до ліцензійного ключа: доки до цього сервера не під'єднано обліковий запис, модуль не може отримати своє право і не показуватиме жодних пристроїв. Під'єднайте обліковий запис у Налаштування ▸ Система ▸ Cloud.",
