  "v2.set.peakMeter": "Піковий індикатор",
  "v2.set.peakMeterHint": "Лише відображення — сигнал не змінюється. Панель відтворення показує лише лампи: дві шкали для неї заширокі.",
  "v2.set.barVu": "Панель відтворення з VU-метрами",
  "v2.set.barVuHint": "Лише відображення — сигнал не змінюється. Два стрілкові індикатори обабіч елементів керування; вони замінюють пікові лампи та міні-спектр. На вузькій панелі повертається звичайна панель.",
  "v2.set.barOnde": "Смуга прогресу у вигляді хвилі",
  "v2.set.barOndeHint": "Лише відображення. Смуга прогресу на екрані «Зараз грає» та на панелі відтворення малює форму хвилі треку: відтворена частина кольорова, решта приглушена. Для треків бібліотеки; стрімінг і радіо зберігають звичайну смугу.",
  "v2.set.barViz": "Візуалізатор на панелі відтворення",
  "v2.set.barVizHint": "Показує маленький смуговий візуалізатор (спектр) праворуч на панелі відтворення, поруч із серцем. Лише відображення: звук не змінюється.",
