  "v2.hint.defaultZone": "Зона, вибрана під час запуску, якщо жодної не було вибрано. Трек, запущений не замислюючись, піде туди.",
  "v2.hint.volumeDisplay": "Як записується гучність. Децибели показують реальне підсилення; відсотки — це шкала відображення, а не вимірювання.",
  "v2.hint.ingestMode": "🔴 «Перемістити» прибирає файл із початкового місця. «Копіювати» залишає його там і займає вдвічі більше місця.",
  "v2.hint.audioBackend": "Драйвер, через який виходить звук. ASIO потребує драйвера від виробника; без нього вихід мовчить.",
  "v2.hint.wasapiMode": "В ексклюзивному режимі Tune займає звукову карту лише для себе: потік іде bit-perfect, але інші застосунки замовкають.",
  "v2.hint.replayGainPreamp": "Зсув, що застосовується понад ReplayGain. Підвищення рівня наближає піки до кліпінгу — саме для цього потрібен захист від кліпінгу.",
