  "cloudBackup.title": "Резервне копіювання в хмару",
  "cloudBackup.intro": "Tune створює резервні копії ваших налаштувань у Mozaiklabs, зашифровані на цьому сервері ключем, якого Mozaiklabs не знає: налаштування, зони, профілі та вподобання, еквалайзери, обране, плейлисти й радіостанції. Ніколи вашу бібліотеку, а також паролі й токени сервісів, за одним винятком: токен Discogs передається зашифрованим разом з іншим. Зберігається щонайбільше три знімки на машину й п'ять машин на обліковий запис; найстаріші видаляються.",
